/**
 * The Drizzle schema — PLAN.md §5.2.
 *
 * Conventions every table here follows, stated once:
 *
 *   - primary keys are `uuid ... DEFAULT uuidv7()`, generated by the database;
 *   - every mutable row carries the audit quartet — `created_at`, `created_by`,
 *     `updated_at`, `updated_by` — join tables and reference tables included;
 *   - content rows carry `entity_id`, `version` and a nullable `proposal_id`, and **a read
 *     that forgets `proposal_id IS NULL` returns proposals to the public**;
 *   - every `<type>_content` carries `name` and `abstract`, by convention rather than
 *     inheritance — `registry.test.ts` is what keeps the convention true.
 *
 * `registry.ts` is the list a new entity type has to join. The closure invariant and the
 * proposal conformance test both read it, so a type left out of it is a type nobody guards.
 *
 * Import this barrel rather than a table module: the audit columns reference the entity
 * table, and the modules resolve that lazily.
 */

export * from "./authorization";
export * from "./columns";
export * from "./discussion";
export * from "./entity";
export * from "./enums";
export * from "./link";
